        "Note",
        """<strong>Hannah’s vow.</strong> Hannah dedicates her unborn son as a lifelong Nazirite — a vow to be ratified later (1 Sam 1:22 with the implicit Nazirite framework of Num 6). Compare Samson (Judg 13). The vow is hers alone — Elkanah’s ratifying role appears only in Num 30:10–15 logic. Hannah’s silent prayer in 1:13 became, in rabbinic tradition (b. Berakhot 31a), the model for the <em>Amidah</em> — the central standing prayer of Jewish liturgy.""",
