    (
        5,
        6,
        "",
        "tumors",
        "comm",
        "Note",
        "Note",
        """<strong>The plague of tumors.</strong> The Hebrew <em>‘ofalim</em> describes swellings traditionally rendered "emerods" (older English) or "tumors"; the LXX glosses <em>edras</em> (in the rear). Combined with the golden-mouse offering of 6:5, many scholars (going back to nineteenth-century commentators and refined by twentieth-century medical historians) have proposed bubonic plague, with the mice/rats functioning as the recognized vector — though the text gives no explicit causal link, and the medical retrojection is necessarily speculative. The narrative point doesn’t depend on the diagnosis: the disease functions theologically as a counter-plague to the Egyptian plagues of Exod 7–12 (cf. 6:6 — "why do you harden your hearts as the Egyptians… hardened their hearts?"), with the Philistines now in the role Egypt played and the Ark functioning as the inverted instrument of judgment.""",
        "User paraphrase; references LXX",
    ),
