    (
        6,
        4,
        "",
        "Five golden tumors and five golden mice",
        "comm",
        "Note",
        "Note",
        """<strong>The trespass offering.</strong> The Philistine priests prescribe a classic ANE healing-by-image practice: replicate the affliction in precious metal and send it back with the offending object as a placation offering. Identical reasoning underlies medieval ex-voto images (a wax leg offered to a saint for a healed leg) and recurs across early-modern folk healing traditions. The narrative is not endorsing the practice — Yahweh has not requested it — but recording the Philistines’ best guess at how to stop the plague using their own theological framework. The number five corresponds to the five Philistine city-states (Gaza, Ashkelon, Ashdod, Gath, Ekron — the traditional Pentapolis listed at 6:17), the canonical political configuration of the Philistine confederacy.""",
        "User original",
    ),
