    (
        9,
        21,
        "",
        "Am I not a Benjamite, of the smallest of the tribes of Israel?",
        "comm",
        "Note",
        "Note",
        """<strong>The smallest tribe.</strong> Saul’s self-deprecating reply is more pointed than humility-formula: Benjamin had been all but exterminated in Judg 19–21, the closing horror of the Judges era — only six hundred men survived the inter-tribal civil war that followed the Levite’s concubine episode. Israel’s first king is drawn from the tribe Israel itself had nearly wiped out a generation earlier. The narrative irony is heavy: monarchy emerges from the wound of the prior era, and Saul’s rule will end in another civil war between tribes. The pattern of choosing leaders from the marginal — younger sons, smaller tribes, women, foreigners — is the OT’s recurrent preference, and Saul’s case is one of its starkest. The choice also anticipates Paul’s own self-identification as "of the tribe of Benjamin" (Phil 3:5, Rom 11:1) centuries later.""",
        "User original",
    ),
