    (
        15,
        22,
        "",
        "to obey is better than sacrifice",
        "comm",
        "Note",
        "Note",
        """<strong>Obedience over sacrifice.</strong> One of the great prophetic-cultic critiques in the Hebrew Bible — anticipating Hosea 6:6, Amos 5:21–24, Micah 6:6–8, Isaiah 1:11–17. The prophets do not abolish sacrifice but subordinate it to ethical and relational fidelity. Jesus quotes Hosea 6:6 ("I desire mercy, not sacrifice," Matt 9:13, 12:7) in the same tradition. Samuel’s formulation here is one of the canon’s earliest articulations of this hierarchy.""",
        "User original",
    ),
