    (
        16,
        7,
        "",
        "Yahweh looks at the heart",
        "comm",
        "Note",
        "Note",
        """<strong>Heart, not appearance.</strong> The verse is given as the principle behind David’s selection — not the tall handsome eldest sons but the youngest shepherd boy is chosen. The interior-vs-exterior antithesis becomes a recurring biblical motif (Jer 17:10, 1 Pet 3:3–4). The verse also has dramatic irony: the narrator immediately notes that David <em>was</em> beautiful (16:12). The text doesn’t deflate the heart-criterion; it complicates it.""",
        "User original",
    ),
