    (
        16,
        14,
        "",
        "an evil spirit from Yahweh",
        "comm",
        "Note",
        "Note",
        """<strong>The "evil spirit from Yahweh."</strong> The text’s framing — God as the immediate source of all causation, including troubling spiritual states — has troubled later monotheistic harmonization. The Bible is consistently willing to attribute to Yahweh what later theology might attribute to permission, secondary causes, or demonic agency. Compare Saul’s "evil spirit" here with Job’s satan (a heavenly accuser still under God’s control), 1 Kgs 22:19–23 (the lying spirit), and 2 Sam 24:1 (Yahweh inciting David, recast as Satan in 1 Chr 21:1). The OT theology of dual causation is unsystematic by design.""",
        "User original",
    ),
