    (
        22,
        18,
        "",
        "Doeg the Edomite",
        "comm",
        "Note",
        "Note",
        """<strong>The slaughter at Nob.</strong> Doeg the Edomite — a non-Israelite court official — executes eighty-five priests when Saul’s own bodyguards refuse the order. The episode is the OT’s starkest portrait of state-sponsored cultic violence by an Israelite king, surpassing in horror anything earlier in the canon. Three things mark its theological weight: the killers are non-Israelite mercenaries (the king’s own troops have a moral line they will not cross), the victims are priests of Yahweh wearing the linen ephod, and one survivor (Abiathar) escapes to David carrying the ephod that will function as David’s oracle through the rest of the book. Saul’s rejection by Yahweh, prophesied in chs 13 and 15, becomes an institutional and moral fact in this chapter. Psalm 52 is traditionally attached to this episode, addressed to Doeg. The shedding of priestly blood is the unredeemable charge that marks the end of the Saulide regime in moral terms long before it ends militarily.""",
        "User original",
    ),
