        "Note",
        "<strong>The bride-price gambit.</strong> Saul demands an unpayable bride-price hoping David will die in the attempt — a classic ANE narrative motif (cf. Bellerophon and the Chimaera in the Iliad, Hipparkhia’s tasks in Mesopotamian tradition) inverted: the king who tries to kill the hero through impossible task is overcome by the hero’s success. Hebrew bride-prices typically involved silver or livestock (Gen 34:12, Deut 22:29); Saul’s demand for foreskins is theological and political — proof of dead Philistines combined with a humiliating violation of the enemy dead, since circumcision was the marker of covenant identity (Gen 17). David doubles the price (200 foreskins, 18:27), an act of reckless devotion that secures the marriage to Michal but seals Saul’s view of him as a threat the throne cannot absorb. The episode foreshadows the Bathsheba pattern decades later: David’s sexual-political ambitions producing collateral death.",
