        "Note",
        "Note",
        """<strong>The cave of Adullam.</strong> David’s first base of operations as a fugitive — and the foundational site of his irregular military force. The verse following (22:2) describes those who gathered: "everyone who was in distress, in debt, and discontented." Four hundred men (later six hundred, 23:13) form a paramilitary band of socially marginal Israelites, the sociological core of what will later become David’s royal guard and the original "mighty men" listed in 2 Sam 23. The political significance is sharp: the Davidic regime is built first from below, by the disaffected and dispossessed of Saul’s kingdom, before it ever assumes formal power. The pattern — a king whose original constituency is the marginal — runs through Davidic theology and is picked up explicitly in NT framings of Jesus’ early followers (Matt 11:28, "all you who are weary and burdened"). The cave itself, located in the Shephelah, was a natural refuge frequently attested in subsequent guerrilla warfare in the same terrain.""",
