        """<strong>Tz’ror ha-ḥayyim (<em>צְרוֹר</em> <em>הַחַיִּים</em>).</strong> "The bundle of the living" — Abigail’s phrase for the secure existence of those preserved by Yahweh, contrasted with souls "slung out as from a sling’s pocket." The image is concrete: a bundle (<em>tz’ror</em>) is a pouch in which valuables are tied for keeping; Yahweh keeps the lives of the faithful as a man keeps his treasure. The phrase enters Jewish liturgical tradition as one of the great eschatological formulas: <em>titztzor bi-tz’ror ha-ḥayyim</em> ("may [his/her soul] be bound up in the bundle of the living") is the standard inscription on Jewish gravestones to this day, and the Hebrew acronym <em>תנצב"ה</em> (T-N-Tz-B-H) on virtually every Jewish tombstone abbreviates this verse. Few biblical phrases have had so durable a liturgical-funerary afterlife.""",
