        "Note",
        "Note",
        """<strong>Exile as forced apostasy.</strong> David articulates a theological principle of Israelite religious geography: to be driven from Yahweh’s land is, functionally, to be told "go, serve other gods" (26:19). The premise — that Yahweh’s effective worship is bound to Yahweh’s territory — is shared widely across early Israelite religion (cf. Naaman taking earth from Israel back to Aram, 2 Kgs 5:17) and only later modified by the exilic prophets (Jer 29, Ezek 11) into a theology of Yahweh present in exile. Davidic complaint here, on the cusp of his actual flight to Philistine Gath, registers the agony of forced removal from cult-territory in terms the post-exilic reader of Lamentations and Psalm 137 will recognize. The verse is one of the OT’s clearest articulations of the territorial dimension of pre-exilic Yahwism.""",
