        "comm",
        "Note",
        "Note",
        """<strong>David’s double game.</strong> While taking refuge under Achish of Gath, David systematically raids the southern tribes — Geshurites, Girzites, Amalekites — leaving no survivors who could report his activity, then tells Achish he has been raiding Judah and its allies (27:10–12). The deception serves three ends: he protects Achish’s trust, he weakens Israel’s southern enemies (which will pay off when he becomes king), and he distributes the spoil to Judah’s elders (30:26–31), building political support for his eventual return. The narrative does not moralize the deceit; it presents it as the political competence that distinguishes David’s exile from Saul’s. The Amalekite raids in particular complete unfinished business from ch 15 — Saul lost his kingship for sparing Amalekites, David secures his by exterminating them. The strategic asymmetry is the chapter’s argument.""",
