        "Note",
        """<strong>The Jabesh-Gileadites’ retrieval.</strong> The men of Jabesh-Gilead retrieve the bodies of Saul and his sons from the Philistine wall at Beth-Shan, cremate them, and bury the bones — an unusual procedure (cremation is generally not standard Israelite practice; cf. 2 Sam 21:12–14, where the bones are later re-buried in Saul’s ancestral tomb in Benjamin) likely undertaken because the bodies were too desecrated for normal burial. The act closes a long-running narrative arc: Saul’s first major military victory was the rescue of Jabesh-Gilead from Nahash the Ammonite (ch 11), and these are the same people now risking themselves to honor their dead deliverer. The chapter ends not with Saul’s defeat but with this gesture of remembered loyalty — the small kindness that frames the failed king’s death is the gratitude of the people he saved at his beginning. David will explicitly bless them for it (2 Sam 2:5–7).""",
